using System;using System.IO;using System.Collections;using System.Reflection;using System.Globalization;using UnityEngine;
namespace ValheimLab{public sealed class WorldgenCheck:MonoBehaviour{
const BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;string output;static string F(float x){return x.ToString("R",CultureInfo.InvariantCulture);}
void Start(){output=Path.Combine(Probe.LabRoot,"private-cache","worldgen","native-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fffffff"));Directory.CreateDirectory(output);StartCoroutine(Run());}
IEnumerator Run(){yield return new WaitForSecondsRealtime(8);try{if(FileHelpers.CloudStorageSupportedAndEnabled)throw new Exception("Cloud isolation failed");var w=new World("WorldgenReference","LabTerrain1");WorldGenerator.Initialize(w);var g=WorldGenerator.instance;float offset=(float)typeof(WorldGenerator).GetField("m_offset3",Flags).GetValue(g);var bas=typeof(WorldGenerator).GetMethod("GetBaseHeight",Flags);var meadow=typeof(WorldGenerator).GetMethod("GetMeadowsHeight",Flags);var river=typeof(WorldGenerator).GetMethod("AddRivers",Flags);
using(var csv=new StreamWriter(Path.Combine(output,"meadows.csv"))){csv.WriteLine("x,z,base,n01,n02,n05,n10,n40,riverInput,riverOutput,expected");for(int i=0;i<512;i++){float x=i<256?-96+(i%16)*4.125f:-4000+(i%16)*503.73f,z=i<256?-96+(i/16)*4.25f:-4000+((i-256)/16)*497.37f;double a=(float)((double)x+100000+offset),b=(float)((double)z+100000+offset);float n01=DUtils.PerlinNoise(a*(double)0.01f,b*(double)0.01f),n02=DUtils.PerlinNoise(a*(double)0.02f,b*(double)0.02f),n05=DUtils.PerlinNoise(a*(double)0.05f,b*(double)0.05f),n10=DUtils.PerlinNoise(a*(double)0.1f,b*(double)0.1f),n40=DUtils.PerlinNoise(a*(double)0.4f,b*(double)0.4f);float h=(float)bas.Invoke(g,new object[]{x,z,false});float n=(float)((double)n01*n02);n=(float)((double)n+(double)n05*n10*n*0.5);float v=(float)((double)h+(double)n*(double)0.1f);float delta=(float)((double)v-(double)0.15f);float weight=(float)Math.Max(0,Math.Min(1,(double)h/(double)0.4f));if(delta>0)v=(float)((double)v-(double)delta*(1-(double)weight)*0.75);float r=(float)river.Invoke(g,new object[]{x,z,v});float expected=(float)meadow.Invoke(g,new object[]{x,z});csv.WriteLine(F(x)+","+F(z)+","+F(h)+","+F(n01)+","+F(n02)+","+F(n05)+","+F(n10)+","+F(n40)+","+F(v)+","+F(r)+","+F(expected));}}
using(var csv=new StreamWriter(Path.Combine(output,"hashes.csv"))){csv.WriteLine("utf16hex,hash");foreach(string s in new[]{"","a","ab","LabTerrain1","Valheim","å世界","emoji😀","a\0b"}){var hex="";foreach(char c in s)hex+=((int)c).ToString("X4");csv.WriteLine(hex+","+s.GetStableHashCode());}}
using(var csv=new StreamWriter(Path.Combine(output,"noise.csv"))){csv.WriteLine("x,z,value");for(int i=0;i<1024;i++){float x=(i%32-16)*0.173f,z=(i/32-16)*0.217f;csv.WriteLine(F(x)+","+F(z)+","+F(Mathf.PerlinNoise(x,z)));}}
File.WriteAllText(Path.Combine(output,"identity.txt"),"seed="+w.m_seed+"\noffset3="+F(offset)+"\ngenVersion="+w.m_worldGenVersion+"\nUnity="+Application.unityVersion+"\nInputs base/noise/river are native oracle values; not independently generated.\n");File.WriteAllText(Path.Combine(output,"SUCCESS.txt"),"512 Meadows stage checkpoints,1024 native noise samples,8 seed hash vectors");File.WriteAllText(Path.Combine(Probe.LabRoot,"private-cache","worldgen","native-current.txt"),output);Application.Quit(0);}catch(Exception e){File.WriteAllText(Path.Combine(output,"FAILED.txt"),e.ToString());Debug.LogError(e);Application.Quit(2);}}
}}
